-- Moqoqo initial schema. Plain SQL that runs on PostgreSQL 16+ and PGlite.
-- Money is stored as integer cents (bigint). Ids are random UUID strings generated by the app.

CREATE TABLE users (
  id             text PRIMARY KEY,
  msisdn         text UNIQUE,                 -- E.164; NULL for system accounts (billers)
  name           text NOT NULL,
  role           text NOT NULL CHECK (role IN ('customer', 'agent', 'merchant')),
  kind           text NOT NULL DEFAULT 'person' CHECK (kind IN ('person', 'system')),
  official       boolean NOT NULL DEFAULT false,
  business_name  text,
  code           text UNIQUE,                 -- AGENT-0101, TAXI-0042, MRC-0001
  biller         text UNIQUE,                 -- BillKey for biller system accounts
  kyc_tier       integer NOT NULL DEFAULT 1 CHECK (kyc_tier IN (1, 2)),
  balance_cents  bigint NOT NULL DEFAULT 0 CHECK (balance_cents >= 0),
  pin_hash       text,                        -- NULL: cannot log in
  pin_salt       text,
  failed_pins    integer NOT NULL DEFAULT 0,
  locked_until   timestamptz,
  status         text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  created_at     timestamptz NOT NULL DEFAULT now(),
  last_seen_at   timestamptz
);
CREATE INDEX users_role_idx ON users (role);

CREATE TABLE sessions (
  token_hash    text PRIMARY KEY,
  user_id       text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  app           text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_used_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

CREATE TABLE chats (
  id          text PRIMARY KEY,
  kind        text NOT NULL CHECK (kind IN ('direct', 'group', 'official')),
  title       text,                          -- groups only
  pair_key    text UNIQUE,                   -- direct/official: sorted member ids, makes get-or-create race free
  created_by  text REFERENCES users (id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE chat_members (
  chat_id       text NOT NULL REFERENCES chats (id) ON DELETE CASCADE,
  user_id       text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  joined_at     timestamptz NOT NULL DEFAULT now(),
  last_read_at  timestamptz,
  PRIMARY KEY (chat_id, user_id)
);
CREATE INDEX chat_members_user_idx ON chat_members (user_id);

CREATE TABLE messages (
  seq           bigserial UNIQUE,            -- stable ordering and cursor
  id            text PRIMARY KEY,
  chat_id       text NOT NULL REFERENCES chats (id) ON DELETE CASCADE,
  sender_id     text NOT NULL REFERENCES users (id),
  client_id     text,
  kind          text NOT NULL CHECK (kind IN ('text', 'money', 'mpho', 'request', 'receipt', 'system')),
  text          text,
  amount_cents  bigint,
  note          text,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX messages_chat_seq_idx ON messages (chat_id, seq);
CREATE UNIQUE INDEX messages_client_idx ON messages (chat_id, sender_id, client_id);

-- Payment requests (Kopa / Ntefelle / cash-out / merchant charge). One row per request message.
CREATE TABLE requests (
  message_id     text PRIMARY KEY REFERENCES messages (id) ON DELETE CASCADE,
  kind           text NOT NULL CHECK (kind IN ('money', 'bill', 'cashout', 'merchant')),
  requester_id   text NOT NULL REFERENCES users (id),
  to_user_id     text NOT NULL REFERENCES users (id),
  amount_cents   bigint NOT NULL CHECK (amount_cents > 0),
  paid_cents     bigint NOT NULL DEFAULT 0 CHECK (paid_cents >= 0),
  status         text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'declined', 'cancelled')),
  bill           text,
  account        text,
  detail         text,
  note           text,
  paid_by_name   text,
  updated_at     timestamptz NOT NULL DEFAULT now(),
  CHECK (paid_cents <= amount_cents)
);
CREATE INDEX requests_requester_idx ON requests (requester_id, kind, status);

-- The ledger. from/to NULL = outside the wallet system (bank float deposit).
CREATE TABLE transactions (
  id            text PRIMARY KEY,
  reference     text NOT NULL UNIQUE,
  kind          text NOT NULL CHECK (kind IN ('send', 'mpho', 'request', 'bill', 'merchant', 'tap', 'cashin', 'cashout', 'float', 'register')),
  amount_cents  bigint NOT NULL CHECK (amount_cents >= 0),
  from_user_id  text REFERENCES users (id),
  to_user_id    text REFERENCES users (id),
  label         text,                         -- e.g. 'LEC token · 04128890113'
  note          text,
  message_id    text,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX transactions_from_idx ON transactions (from_user_id, created_at);
CREATE INDEX transactions_to_idx ON transactions (to_user_id, created_at);
CREATE INDEX transactions_created_idx ON transactions (created_at);

CREATE TABLE devices (
  expo_push_token  text PRIMARY KEY,
  user_id          text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  platform         text NOT NULL,
  app              text NOT NULL,
  updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX devices_user_idx ON devices (user_id);

CREATE TABLE maintenance_windows (
  id          text PRIMARY KEY,
  starts_at   timestamptz NOT NULL,
  ends_at     timestamptz NOT NULL,
  message_en  text NOT NULL,
  message_st  text NOT NULL,
  cancelled   boolean NOT NULL DEFAULT false,
  created_by  text NOT NULL,                 -- admin email
  created_at  timestamptz NOT NULL DEFAULT now(),
  CHECK (ends_at > starts_at)
);
CREATE INDEX maintenance_windows_time_idx ON maintenance_windows (starts_at, ends_at);

CREATE TABLE app_settings (
  key         text PRIMARY KEY,
  value       jsonb,
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE admins (
  id             text PRIMARY KEY,
  email          text NOT NULL UNIQUE,
  name           text NOT NULL,
  role           text NOT NULL CHECK (role IN ('admin', 'support')),
  password_hash  text NOT NULL,
  password_salt  text NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE admin_sessions (
  token_hash  text PRIMARY KEY,
  admin_id    text NOT NULL REFERENCES admins (id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE audit_log (
  seq          bigserial UNIQUE,
  id           text PRIMARY KEY,
  admin_id     text REFERENCES admins (id),
  admin_email  text NOT NULL,
  action       text NOT NULL,
  target       text NOT NULL,
  detail       text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now()
);
